        clipboard_text = clipboard_text.replace('\\\\', '\\\\\\\\')
        clipboard_text = clipboard_text.replace('"', '\\\\"')
        clipboard_text = clipboard_text.replace('\\n', '\\\\n')
        clipboard_text = clipboard_text.replace('\\r', '\\\\r')
        clipboard_text = clipboard_text.replace('\\t', '\\\\t')
        
